                    match ustd::stat(p) {
                        Ok(st) => t.emit(&alloc::format!(
                            "{} {}",
                            flags(st.attr, st.is_dir != 0),
                            p
                        )),
                        Err(e) => t.fail(&alloc::format!("lsattr: {}: err {}", p, e)),
                    }
