                                {
                                    let base = f
                                        .trim_end_matches('/')
                                        .rsplit('/')
                                        .next()
                                        .unwrap_or(f);
                                    dst = alloc::format!(
                                        "{}/{}",
                                        dst.trim_end_matches('/'),
                                        base
                                    );
                                }
                                let body = alloc::format!("LNK>{}", tgt);
